head.b:skin:
/*
=====================================================
 News Portal Blogger Theme  (single-file template)
 Layout: navy header, Selected Articles slider,
 Latest Business sidebar, Life Style + Gadgets columns,
 Latest Articles grid, Load More, navy footer.
 Responsive, mobile friendly, animated, dark mode.
 Edit colours in :root below.
=====================================================
*/

:root{
  --navy:#0d2b66;
  --navy-d:#081d47;
  --navy-l:#1d4f9f;
  --yellow:#f6c600;
  --red:#e5382d;
  --bg:#ffffff;
  --soft:#f3f6fb;
  --card:#ffffff;
  --text:#1b2433;
  --mut:#6a7585;
  --line:#e2e8f1;
  --shadow:0 8px 26px rgba(13,43,102,.12);
  --font:'Roboto',system-ui,-apple-system,'Segoe UI',Arial,sans-serif;
}
[data-theme='dark']{
  --bg:#0a1222;
  --soft:#101a2f;
  --card:#101a2f;
  --text:#e9eefa;
  --mut:#95a4bf;
  --line:#1f2d4a;
  --shadow:0 8px 26px rgba(0,0,0,.45);
}

*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font);background:var(--bg);color:var(--text);line-height:1.55;font-size:15px;transition:background .3s,color .3s}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4,p{margin:0}
button{font-family:inherit;cursor:pointer;border:0;background:none;color:inherit}
:focus-visible{outline:3px solid var(--yellow);outline-offset:2px;border-radius:4px}
.wrap{max-width:1240px;margin:0 auto;padding:0 18px}

/* first letter accent used on titles */
.fl::first-letter{color:var(--red);font-size:1.3em;font-weight:500}

/* ---------- reading progress ---------- */
#rp{position:fixed;top:0;left:0;height:4px;width:0;background:var(--yellow);z-index:300;transition:width .1s linear}

/* ---------- header ---------- */
.site-header{position:sticky;top:0;z-index:100;background:linear-gradient(110deg,var(--navy-d),var(--navy) 50%,#143a85);background-size:200% 200%;animation:gradShift 14s ease infinite;color:#fff;box-shadow:0 2px 0 rgba(0,0,0,.08);transition:box-shadow .3s}
.scrolled .site-header,.site-header.scrolled{box-shadow:0 8px 24px rgba(0,0,0,.3)}
.bar{display:flex;align-items:center;gap:22px;height:64px;transition:height .25s}
.site-header.scrolled .bar{height:54px}
.logo{display:flex;align-items:center;gap:8px;flex-shrink:0}
.logo svg{width:34px;height:34px;animation:popIn .8s cubic-bezier(.2,1.4,.4,1) both}
.logo b{font:900 24px/1 var(--font);letter-spacing:.5px;text-transform:uppercase}
.nav{display:flex;gap:2px;flex:1;margin-left:26px}
.nav a{position:relative;padding:8px 13px;font-weight:500;font-size:14.5px;color:#d7e3ff;transition:color .2s}
.nav a:hover{color:#fff}
.nav a::after{content:'';position:absolute;left:13px;right:13px;bottom:2px;height:2px;background:var(--yellow);transform:scaleX(0);transform-origin:left;transition:transform .3s}
.nav a:hover::after{transform:scaleX(1)}
.actions{display:flex;align-items:center;gap:8px;margin-left:auto}
.cta{background:var(--yellow);color:#1b2433;font-weight:700;font-size:14px;padding:7px 18px;border-radius:999px;animation:pulse 2.6s infinite}
.icon-btn{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;color:#fff;transition:background .2s,transform .2s}
.icon-btn:hover{background:rgba(255,255,255,.16);transform:scale(1.1)}
.icon-btn svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}
.burger{display:none}

.drawer{position:fixed;inset:0 0 0 auto;width:min(300px,84vw);background:var(--navy-d);color:#fff;z-index:150;transform:translateX(105%);transition:transform .35s cubic-bezier(.2,.8,.2,1);padding:70px 20px 20px;display:flex;flex-direction:column;overflow:auto}
.drawer.open{transform:none}
.drawer a{padding:12px 10px;border-radius:8px;font-weight:500}
.drawer a:hover{background:rgba(255,255,255,.1)}
.drawer .x{position:absolute;top:14px;right:14px}
.scrim{position:fixed;inset:0;background:rgba(3,10,30,.55);backdrop-filter:blur(3px);opacity:0;pointer-events:none;transition:opacity .3s;z-index:140}
.scrim.open{opacity:1;pointer-events:auto}
.search-ov{position:fixed;inset:0;z-index:160;background:rgba(8,29,71,.96);display:grid;place-items:center;padding:20px;opacity:0;pointer-events:none;transition:opacity .3s}
.search-ov.open{opacity:1;pointer-events:auto}
.search-ov form{width:min(680px,100%);transform:translateY(20px);transition:transform .35s}
.search-ov.open form{transform:none}
.search-ov input{width:100%;font:500 clamp(20px,4vw,32px) var(--font);padding:16px 4px;color:#fff;background:none;border:0;border-bottom:3px solid var(--yellow);outline:0}
.search-ov input::placeholder{color:rgba(255,255,255,.5)}
.search-ov .x{position:absolute;top:20px;right:20px}

/* ---------- headings / small parts ---------- */
.sec-h{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}
.sec-h h2{font:700 21px/1.2 var(--font);display:flex;align-items:center;gap:8px}
.stars{color:var(--text);letter-spacing:-1px;font-size:15px}
.see{font-size:12px;font-weight:500;border:1px solid var(--navy-l);color:var(--navy-l);padding:4px 12px;border-radius:3px;white-space:nowrap;transition:background .25s,color .25s,transform .25s}
.see:hover{background:var(--navy-l);color:#fff;transform:translateX(3px)}
[data-theme='dark'] .see{color:#8fb4ff;border-color:#8fb4ff}
.chip{display:inline-block;background:#2b2f3a;color:#fff;font-size:11px;font-weight:700;padding:3px 9px;line-height:1.5;text-transform:uppercase;letter-spacing:.3px}
.chip.blue{background:var(--navy-l)}
.meta{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:12px;color:var(--mut)}
.thumb{overflow:hidden;background:var(--line);display:block}
.thumb img{width:100%;height:100%;object-fit:cover;transition:transform .6s cubic-bezier(.2,.8,.2,1)}
a:hover>img,a:hover>.thumb img,.thumb:hover img{transform:scale(1.07)}

/* ---------- home layout ---------- */
#home{display:none;padding:22px 0 10px}
.is-home #home{display:block}
.is-home .page-grid{display:none}
.home-grid{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:34px}
.home-main>section{margin-bottom:34px}

/* Selected articles slider */
.slides{display:grid}
.slide{grid-area:1/1;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:22px;align-items:start;opacity:0;visibility:hidden;transition:opacity .7s ease,visibility .7s}
.slide.on{opacity:1;visibility:visible;z-index:1}
.slide .pic{display:block;overflow:hidden;aspect-ratio:16/10;background:var(--line);box-shadow:var(--shadow)}
.slide .pic img{width:100%;height:100%;object-fit:cover}
.slide.on .pic img{animation:kenburns 9s ease-out both}
.slide h3{font:500 clamp(22px,2.6vw,30px)/1.25 var(--font);margin:12px 0 10px}
.slide .meta{margin-bottom:12px}
.slide p{color:var(--mut);font-size:14.5px}
.dots{display:flex;gap:8px;margin-top:14px}
.dots button{width:26px;height:4px;background:var(--line);border-radius:2px;position:relative;overflow:hidden}
.dots button.on::after{content:'';position:absolute;inset:0;background:var(--navy-l);transform-origin:left;animation:fillBar 6s linear both}

/* two columns */
.two-col{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:30px}
.mini{display:flex;gap:14px;align-items:flex-start;padding:0 0 16px;margin-bottom:16px;transition:transform .3s}
.mini:hover{transform:translateX(5px)}
.mini .thumb{width:90px;height:64px;flex-shrink:0}
.mini h4{font:700 14.5px/1.35 var(--font)}
.mini:hover h4{color:var(--navy-l)}

/* latest grid */
.latest-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px 16px}
.gcard .gthumb{position:relative;aspect-ratio:16/10;overflow:hidden;background:var(--line);display:block}
.gcard .gthumb .chip{position:absolute;left:0;top:0;font-size:9.5px;padding:2px 8px;background:var(--navy-l);z-index:2}
.gcard h3{font:700 13.5px/1.4 var(--font);margin-top:8px}
.gcard:hover h3{color:var(--navy-l)}
.more-wrap{text-align:center;margin-top:26px}
.btn{display:inline-flex;align-items:center;gap:8px;background:var(--navy-l);color:#fff;font-weight:500;padding:10px 30px;border-radius:3px;border-bottom:3px solid var(--navy);transition:transform .25s,box-shadow .25s}
.btn:hover{transform:translateY(-3px);box-shadow:0 10px 20px rgba(13,43,102,.3)}
.btn[disabled]{opacity:.6;pointer-events:none}
.btn .spin{width:14px;height:14px;border:2px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite;display:none}
.btn.loading .spin{display:inline-block}

/* business sidebar */
.biz-feat{display:block;margin-bottom:22px}
.biz-feat .thumb{aspect-ratio:16/10;box-shadow:var(--shadow)}
.biz-feat h3{font:700 16px/1.4 var(--font);margin-top:12px}
.biz-list .mini{border-bottom:1px solid var(--line);margin-bottom:14px}
.biz-list .mini:last-child{border-bottom:0}
.biz-list .mini .thumb{width:84px;height:62px}
.side-ad{margin-top:26px}
.widget-content img{max-width:100%}
.ad{position:relative;overflow:hidden;min-height:280px;color:#fff;padding:26px 22px;background:linear-gradient(135deg,#081d47,#0d2b66,#1f6fe5,#0d2b66);background-size:300% 300%;animation:gradShift 9s ease infinite}
.ad h3{font:900 28px/1.15 var(--font);position:relative;z-index:2}
.ad p{margin:10px 0 16px;opacity:.9;position:relative;z-index:2}
.ad .btn-gold{position:relative;z-index:2;display:inline-block;background:var(--yellow);color:#1b2433;font-weight:700;padding:9px 18px;border-radius:4px;transition:transform .25s}
.ad .btn-gold:hover{transform:translateY(-3px)}
.ad .orb{position:absolute;border-radius:50%;background:rgba(246,198,0,.18);animation:floaty 7s ease-in-out infinite}
.ad .o1{width:150px;height:150px;right:-40px;top:-30px}
.ad .o2{width:80px;height:80px;left:40%;bottom:70px;background:rgba(255,255,255,.1);animation-delay:-2s}
.ad .lap{position:absolute;right:-14px;bottom:-4px;width:70%;animation:floaty 5s ease-in-out infinite}

/* skeleton + reveal */
.sk{position:relative;overflow:hidden;background:var(--line)}
.sk::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.45),transparent);transform:translateX(-100%);animation:shimmer 1.4s infinite}
.sk-pic{aspect-ratio:16/10}
.sk-row{height:64px;margin-bottom:16px}
.empty{padding:20px;color:var(--mut);font-size:14px}
.reveal{opacity:0;transform:translateY(16px);transition:opacity .55s ease,transform .55s cubic-bezier(.2,.8,.2,1)}
.reveal.in{opacity:1;transform:none}

/* ---------- inner pages ---------- */
.page-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:30px;padding:24px 0 30px}
.is-index .page-grid:not(:has(.side .widget)),.is-item .page-grid:not(:has(.side .widget)),.is-static_page .page-grid:not(:has(.side .widget)){grid-template-columns:minmax(0,1fr)}
.arch-title{font:700 28px/1.2 var(--font);margin-bottom:18px}
.post-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.post-card{background:var(--card);border:1px solid var(--line);transition:transform .3s,box-shadow .3s}
.post-card:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.post-card img{width:100%;height:190px;object-fit:cover}
.post-card .pc{padding:14px 16px 18px}
.post-card h2{font:700 18px/1.35 var(--font);margin:8px 0}
.post-card p{font-size:13.5px;color:var(--mut)}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:22px}
.post-single{padding:0}
.post-title{font:700 clamp(26px,4vw,38px)/1.2 var(--font);margin:12px 0}
.post-labels{display:flex;flex-wrap:wrap;gap:6px}
.post-body{font-size:17px;line-height:1.85;margin-top:22px;overflow-wrap:anywhere}
.post-body img{max-width:100%;height:auto}
.post-body h2,.post-body h3{margin:1.6em 0 .6em}
.post-body a{color:var(--navy-l);text-decoration:underline}
.post-body blockquote{margin:1.4em 0;padding:12px 18px;border-left:4px solid var(--yellow);background:var(--soft)}
.post-body pre{background:#0b1730;color:#dbe6ff;padding:16px;overflow:auto}
.post-body .separator,.post-body .tr-caption-container{text-align:center!important}
.post-body table{max-width:100%;display:block;overflow:auto}
.share{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:28px;padding-top:18px;border-top:1px solid var(--line);font-weight:700}
.share a{background:var(--soft);border:1px solid var(--line);padding:6px 14px;border-radius:999px;font-size:13px;transition:all .2s}
.share a:hover{background:var(--navy);color:#fff}
#related{margin-top:30px}
.related-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.rel img{aspect-ratio:16/10;width:100%;object-fit:cover}
.rel h4{padding-top:8px;font:700 13.5px/1.4 var(--font)}
.side .widget{border:1px solid var(--line);padding:18px;margin-bottom:18px;background:var(--card)}
.side .widget h3{font:700 17px var(--font);margin-bottom:10px}
.side ul{list-style:none;margin:0;padding:0}
.nf{text-align:center;padding:60px 20px}
.nf h1{font:900 80px var(--font);color:var(--navy-l)}

/* ---------- footer ---------- */
.site-footer{background:var(--navy-d);color:#fff;margin-top:20px;padding:40px 0 22px}
.f-grid{display:grid;grid-template-columns:1.7fr 1fr 1fr 1fr;gap:34px}
.site-footer .logo{margin-bottom:14px}
.site-footer .logo b{color:var(--yellow);font-size:26px}
.site-footer p{font-size:12.5px;color:#b9c7e6;margin-bottom:12px}
.site-footer p a{color:#fff;text-decoration:underline}
.site-footer h4{font:700 17px var(--font);margin-bottom:16px;color:#fff}
.site-footer ul{list-style:none;margin:0;padding:0;display:grid;gap:12px;font-size:14px}
.site-footer ul a{color:#b9c7e6;transition:color .2s,padding .2s}
.site-footer ul a:hover{color:var(--yellow);padding-left:5px}
.social{display:flex;gap:16px;flex-wrap:wrap}
.social a{width:30px;height:30px;color:#fff;display:grid;place-items:center;transition:transform .25s,color .25s}
.social a:hover{transform:translateY(-4px) rotate(8deg);color:var(--yellow)}
.social svg{width:28px;height:28px;fill:currentColor}
.f-badges{display:flex;flex-wrap:wrap;align-items:center;gap:18px;margin-top:30px;padding-top:18px;border-top:1px solid rgba(255,255,255,.12);font-size:12.5px;color:#b9c7e6}
.dmca{background:#2ea44f;color:#fff;font-weight:900;font-size:10px;padding:3px 8px;border-radius:3px;letter-spacing:.3px}
.f-badges a{display:inline-flex;align-items:center;gap:6px}
.f-badges svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2}
.totop{position:fixed;right:0;bottom:44px;width:46px;height:46px;background:#000;color:#fff;display:grid;place-items:center;z-index:120;opacity:0;transform:translateX(100%);transition:opacity .3s,transform .3s}
.totop.show{opacity:1;transform:none}
.totop svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}

/* ---------- motion ---------- */
@keyframes gradShift{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
@keyframes floaty{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-14px) rotate(1.5deg)}}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(246,198,0,.6)}70%{box-shadow:0 0 0 12px rgba(246,198,0,0)}100%{box-shadow:0 0 0 0 rgba(246,198,0,0)}}
@keyframes shimmer{to{transform:translateX(100%)}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes popIn{from{transform:scale(.3) rotate(-120deg);opacity:0}to{transform:none;opacity:1}}
@keyframes kenburns{from{transform:scale(1)}to{transform:scale(1.08)}}
@keyframes fillBar{from{transform:scaleX(0)}to{transform:scaleX(1)}}

/* ---------- responsive ---------- */
@media(max-width:1000px){
  .home-grid{grid-template-columns:1fr}
  .f-grid{grid-template-columns:1fr 1fr}
  .page-grid{grid-template-columns:1fr}
}
@media(max-width:860px){
  .nav{display:none}
  .burger{display:grid}
  .slide{grid-template-columns:1fr}
  .latest-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:600px){
  body{font-size:14px}
  .bar{height:56px;gap:10px}
  .cta{display:none}
  .logo b{font-size:20px}
  .two-col,.post-grid,.f-grid{grid-template-columns:1fr}
  .latest-grid{gap:16px 12px}
  .related-grid{grid-template-columns:1fr 1fr}
  .site-footer{padding:30px 0 18px}
  .totop{bottom:20px}
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
  .reveal{opacity:1;transform:none}
}

body.script:
//
(function(){
'use strict';

/* =========================================================
   SETTINGS  -  edit these to match your blog
   ========================================================= */
var CFG={
  /* top menu: [text, label]  (label = Blogger label name) */
  menu:[['Blogging','Blogging'],['Business','Business'],['Youtube','Youtube'],['Gadgets','Gadgets'],['Technologie','Technologie'],['Android','Android']],
  ctaText:'Cooperation',
  ctaUrl:'/p/contact.html',
  /* home sections: label names ('' = newest posts) */
  selectedLabel:'',
  selectedCount:4,
  selectedTitle:'Selected Articles',
  businessLabel:'Business',
  lifestyleLabel:'Lifestyle',
  lifestyleTitle:'Life Style',
  gadgetsLabel:'Gadgets',
  latestPerPage:6,
  slideSpeed:6000,
  /* social: [svg path key, url, title] keys: fb, in, bsky, rss */
  social:[['fb','https://facebook.com','Facebook'],['in','https://linkedin.com','LinkedIn'],['bsky','https://bsky.app','Bluesky'],['rss','/feeds/posts/default?alt=rss','RSS']]
};
var SOCIAL_SVG={
  fb:'<path d="M12 2a10 10 0 00-1.6 19.9v-7H7.9V12h2.5V9.8c0-2.5 1.5-3.9 3.8-3.9 1.1 0 2.2.2 2.2.2v2.5h-1.3c-1.2 0-1.6.8-1.6 1.6V12h2.8l-.4 2.9h-2.3v7A10 10 0 0012 2z"/>',
  in:'<path d="M4 3h16a1 1 0 011 1v16a1 1 0 01-1 1H4a1 1 0 01-1-1V4a1 1 0 011-1zm3.3 6.5H5v8h2.3v-8zM6.2 5.6a1.3 1.3 0 100 2.6 1.3 1.3 0 000-2.6zM18.6 17.5v-4.4c0-2.2-1.2-3.7-3-3.7-1.2 0-1.8.7-2.1 1.2v-1h-2.3v8h2.3v-4.3c0-1.1.6-1.8 1.4-1.8.9 0 1.3.7 1.3 1.8v4.3h2.4z"/>',
  bsky:'<path d="M6.3 4.5C8.6 6.2 11.2 9.7 12 11.5c.8-1.8 3.4-5.3 5.7-7 1.7-1.2 4.3-2.2 4.3.8 0 .6-.3 5-.5 5.7-.7 2.5-3.2 3.1-5.4 2.7 3.9.7 4.9 2.9 2.7 5.1-4 4.1-5.8-1-6.3-2.3-.1-.2-.1-.3-.1-.2 0-.1 0 0-.1.2-.5 1.3-2.3 6.400-6.300 2.300-2.200-2.200-1.200-4.400 2.700-5.100-2.200.4-4.700-.2-5.400-2.700C2.300 10.300 2 5.900 2 5.300c0-3 2.600-2 4.300-.8z"/>',
  rss:'<circle cx="5" cy="19" r="2.2"/><path d="M3 10v3a8 8 0 018 8h3A11 11 0 003 10zm0-6v3a14 14 0 0114 14h3A17 17 0 003 4z"/>'
};

/* ---------- helpers ---------- */
var $=function(s,c){return(c||document).querySelector(s)};
var $$=function(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function lbl(l){return '/search/label/'+encodeURIComponent(l)}
function fmt(d){try{return new Date(d).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}catch(e){return ''}}
var PH='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="640" height="400"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0d2b66"/><stop offset="1" stop-color="#1f6fe5"/></linearGradient></defs><rect width="640" height="400" fill="url(#g)"/><polygon points="120,300 240,140 320,250 280,300" fill="#fff" opacity=".85"/><polygon points="270,300 360,170 500,300" fill="#f6c600"/></svg>');
function sz(u,w,h){
  if(!u)return PH;
  return u.replace(/\/s\d+(-[a-z]+)*\//,'/w'+w+'-h'+h+'-c/').replace(/=s\d+(-[a-z]+)*(?=$|\?)/,'=w'+w+'-h'+h+'-c');
}
function parse(e){
  var lk=(e.link||[]).filter(function(l){return l.rel==='alternate'})[0];
  var html=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';
  var m=html.match(/<img[^>]+src=["']([^"']+)/i);
  var img=e.media$thumbnail?e.media$thumbnail.url:(m?m[1]:'');
  var text=html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
  return{
    title:e.title.$t,
    url:lk?lk.href:'#',
    date:fmt(e.published.$t),
    cat:(e.category&&e.category[0])?e.category[0].term:'',
    img:img,
    excerpt:text.slice(0,140)+(text.length>140?'…':'')
  };
}
function getFeed(label,max,start){
  var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+max+'&start-index='+(start||1);
  return fetch(u).then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
    var f=j.feed||{};
    return{total:+((f.openSearch$totalResults||{}).$t||0),posts:(f.entry||[]).map(parse)};
  });
}

/* ---------- reveal on scroll ---------- */
var io=('IntersectionObserver' in window)?new IntersectionObserver(function(es){
  es.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target)}});
},{threshold:.06}):null;
function reveal(root){
  $$('.reveal:not(.in)',root).forEach(function(el,i){
    el.style.transitionDelay=Math.min(i*60,360)+'ms';
    if(io)io.observe(el);else el.classList.add('in');
  });
}

/* ---------- templates ---------- */
function head(title,label,stars){
  return '<div class="sec-h"><h2>'+esc(title)+(stars?' <span class="stars">★★★</span>':'')+'</h2>'+(label?'<a class="see" href="'+lbl(label)+'">See all »</a>':'')+'</div>';
}
function mini(p){
  return '<a class="mini reveal" href="'+esc(p.url)+'"><span class="thumb" style="width:90px;height:64px;flex-shrink:0"><img loading="lazy" alt="'+esc(p.title)+'" src="'+esc(sz(p.img,220,160))+'"/></span><h4>'+esc(p.title)+'</h4></a>';
}
function gcard(p){
  return '<article class="gcard reveal"><a class="gthumb" href="'+esc(p.url)+'">'+(p.cat?'<span class="chip">'+esc(p.cat)+'</span>':'')+
    '<img loading="lazy" alt="'+esc(p.title)+'" src="'+esc(sz(p.img,480,300))+'" style="width:100%;height:100%;object-fit:cover"/></a>'+
    '<h3 class="fl"><a href="'+esc(p.url)+'">'+esc(p.title)+'</a></h3></article>';
}
function skel(n){var s='';for(var i=0;i<n;i++)s+='<div class="sk sk-row"></div>';return s}

/* ---------- header / menu / theme ---------- */
function initChrome(){
  var links=CFG.menu.map(function(m){return '<a href="'+lbl(m[1])+'">'+esc(m[0])+'</a>'}).join('');
  $('#nav').innerHTML=links;
  $('#dnav').innerHTML='<a href="/">Home</a>'+links+'<a href="'+esc(CFG.ctaUrl)+'">'+esc(CFG.ctaText)+'</a>';
  var cta=$('#cta');cta.textContent=CFG.ctaText;cta.href=CFG.ctaUrl;
  $('#social').innerHTML=CFG.social.map(function(s){return '<a href="'+esc(s[1])+'" aria-label="'+esc(s[2])+'" rel="noopener" target="_blank"><svg viewBox="0 0 24 24">'+(SOCIAL_SVG[s[0]]||'')+'</svg></a>'}).join('');
  $('#yr').textContent=new Date().getFullYear();

  var drawer=$('#drawer'),scrim=$('#scrim'),sov=$('#sov');
  function drawerSet(o){drawer.classList.toggle('open',o);scrim.classList.toggle('open',o)}
  $('#bbtn').onclick=function(){drawerSet(true)};
  $('#dclose').onclick=scrim.onclick=function(){drawerSet(false)};
  $$('a',drawer).forEach(function(a){a.addEventListener('click',function(){drawerSet(false)})});
  $('#sbtn').onclick=function(){sov.classList.add('open');setTimeout(function(){$('#sinput').focus()},250)};
  $('#sclose').onclick=function(){sov.classList.remove('open')};
  document.addEventListener('keydown',function(e){if(e.key==='Escape'){sov.classList.remove('open');drawerSet(false)}});

  var root=document.documentElement;
  try{var t=localStorage.getItem('np-theme');if(t)root.setAttribute('data-theme',t)}catch(e){}
  $('#tbtn').onclick=function(){
    var d=root.getAttribute('data-theme')==='dark'?'light':'dark';
    root.setAttribute('data-theme',d);try{localStorage.setItem('np-theme',d)}catch(e){}
  };

  var hdr=$('#hdr'),rp=$('#rp'),pb=$('#postBody'),tt=$('#totop');
  function onScroll(){
    hdr.classList.toggle('scrolled',window.scrollY>30);
    tt.classList.toggle('show',window.scrollY>500);
    if(pb){
      var r=pb.getBoundingClientRect(),tot=r.height-window.innerHeight*.6;
      rp.style.width=Math.max(0,Math.min(100,(-r.top/Math.max(tot,1))*100))+'%';
    }
  }
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();
}

/* ---------- selected articles slider ---------- */
function initSlider(el,posts){
  var host=location.hostname;
  el.innerHTML=head(CFG.selectedTitle,'')+
    '<div class="slides">'+posts.map(function(p,i){
      return '<article class="slide'+(i===0?' on':'')+'"><a class="pic" href="'+esc(p.url)+'"><img alt="'+esc(p.title)+'" src="'+esc(sz(p.img,900,560))+'"'+(i?' loading="lazy"':'')+'/></a><div>'+
        (p.cat?'<span class="chip">'+esc(p.cat)+'</span>':'')+
        '<h3 class="fl"><a href="'+esc(p.url)+'">'+esc(p.title)+'</a></h3>'+
        '<div class="meta"><span>Selected articles '+esc(host)+' — '+esc(p.date)+'</span></div>'+
        '<p>'+esc(p.excerpt)+'</p></div></article>';
    }).join('')+'</div>'+
    (posts.length>1?'<div class="dots">'+posts.map(function(_,i){return '<button aria-label="Slide '+(i+1)+'"'+(i===0?' class="on"':'')+'></button>'}).join('')+'</div>':'');
  if(posts.length<2)return;
  var slides=$$('.slide',el),dots=$$('.dots button',el),cur=0,timer;
  function go(n){
    cur=(n+slides.length)%slides.length;
    slides.forEach(function(s,i){s.classList.toggle('on',i===cur)});
    dots.forEach(function(d,i){d.classList.remove('on');if(i===cur){void d.offsetWidth;d.classList.add('on')}});
  }
  function auto(){clearInterval(timer);timer=setInterval(function(){go(cur+1)},CFG.slideSpeed)}
  dots.forEach(function(d,i){d.onclick=function(){go(i);auto()}});
  el.addEventListener('mouseenter',function(){clearInterval(timer)});
  el.addEventListener('mouseleave',auto);
  auto();
}

/* ---------- home sections ---------- */
function initHome(){
  if(!$('#home')||!document.body.classList.contains('is-home'))return;
  var S=$('#selected'),B=$('#business'),L=$('#lifestyle'),G=$('#gadgets');

  S.innerHTML=head(CFG.selectedTitle,'')+'<div class="slide on" style="opacity:1;visibility:visible"><div class="sk sk-pic"></div><div>'+skel(3)+'</div></div>';
  B.innerHTML=head('Latest Business Articles')+'<div class="sk sk-pic" style="margin-bottom:16px"></div>'+skel(5);
  L.innerHTML=head(CFG.lifestyleTitle,CFG.lifestyleLabel,true)+skel(4);
  G.innerHTML=head('Gadgets',CFG.gadgetsLabel,true)+skel(4);

  getFeed(CFG.selectedLabel,CFG.selectedCount).then(function(r){
    if(!r.posts.length)throw 0;initSlider(S,r.posts);
  }).catch(function(){S.innerHTML=head(CFG.selectedTitle,'')+'<div class="empty">No posts yet. Publish your first post to see it here.</div>'});

  getFeed(CFG.businessLabel,8).then(function(r){
    var p=r.posts;if(!p.length)throw 0;
    var f=p[0];
    B.innerHTML=head('Latest Business Articles',CFG.businessLabel)+
      '<a class="biz-feat reveal" href="'+esc(f.url)+'"><span class="thumb"><img alt="'+esc(f.title)+'" src="'+esc(sz(f.img,700,440))+'"/></span><h3 class="fl">'+esc(f.title)+'</h3></a>'+
      '<div class="biz-list">'+p.slice(1).map(function(x){
        return '<a class="mini reveal" href="'+esc(x.url)+'"><span class="thumb" style="width:84px;height:62px;flex-shrink:0"><img loading="lazy" alt="'+esc(x.title)+'" src="'+esc(sz(x.img,200,150))+'"/></span><h4>'+esc(x.title)+'</h4></a>';
      }).join('')+'</div>';
    reveal(B);
  }).catch(function(){B.innerHTML=head('Latest Business Articles',CFG.businessLabel)+'<div class="empty">Add the label “'+esc(CFG.businessLabel)+'” to your posts to show them here.</div>'});

  function fill(el,title,label,n){
    getFeed(label,n).then(function(r){
      if(!r.posts.length)throw 0;
      el.innerHTML=head(title,label,true)+r.posts.map(mini).join('');reveal(el);
    }).catch(function(){el.innerHTML=head(title,label,true)+'<div class="empty">Add the label “'+esc(label)+'” to your posts to show them here.</div>'});
  }
  fill(L,CFG.lifestyleTitle,CFG.lifestyleLabel,4);
  fill(G,'Gadgets',CFG.gadgetsLabel,4);

  var grid=$('#latestGrid'),btn=$('#loadMore'),start=1,per=CFG.latestPerPage,busy=false;
  grid.innerHTML='';for(var i=0;i<per;i++)grid.innerHTML+='<div><div class="sk sk-pic"></div></div>';
  function load(first){
    if(busy)return;busy=true;btn.classList.add('loading');
    getFeed('',per,start).then(function(r){
      if(first)grid.innerHTML='';
      if(!r.posts.length&&first)grid.innerHTML='<div class="empty">No articles yet.</div>';
      grid.insertAdjacentHTML('beforeend',r.posts.map(gcard).join(''));
      start+=per;reveal(grid);
      if(start>r.total||r.posts.length<per)btn.style.display='none';
    }).catch(function(){btn.style.display='none';if(first)grid.innerHTML='<div class="empty">Could not load articles.</div>'})
    .then(function(){busy=false;btn.classList.remove('loading')});
  }
  btn.onclick=function(){load(false)};
  load(true);
}

/* ---------- related posts on article pages ---------- */
function initRelated(){
  var box=$('#related');if(!box||!document.body.classList.contains('is-item'))return;
  var a=$('.post-labels a');if(!a)return;
  var label=a.textContent.trim(),cur=location.pathname;
  getFeed(label,5).then(function(r){
    var p=r.posts.filter(function(x){return x.url.indexOf(cur)<0}).slice(0,3);
    if(!p.length)return;
    box.innerHTML='<div class="sec-h"><h2>Related Articles</h2></div><div class="related-grid">'+p.map(function(x){
      return '<a class="rel reveal" href="'+esc(x.url)+'"><span class="thumb"><img loading="lazy" alt="'+esc(x.title)+'" src="'+esc(sz(x.img,400,250))+'"/></span><h4>'+esc(x.title)+'</h4></a>';
    }).join('')+'</div>';
    reveal(box);
  }).catch(function(){});
}

initChrome();initHome();initRelated();
})();
